from collections import deque

def resolve(path, cwd, links):
    if not path.startswith('/'):
        path = cwd + '/' + path

    link_count = 0
    result = []  # resolved path components, relative to root

    components = deque(path.split('/'))

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if result:
                result.pop()
        else:
            result.append(comp)
            current = '/' + '/'.join(result)
            if current in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[current]
                if not target.startswith('/'):
                    parent = '/' + '/'.join(result[:-1])
                    target = parent + '/' + target
                # remove the link component itself since it's being replaced
                result.pop()
                new_comps = deque(target.split('/'))
                new_comps.extend(components)
                components = new_comps

    if not result:
        return '/'
    return '/' + '/'.join(result)

